contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will drive Put and Collect. Inputs:
    // - putAmount: amount of wei to send to Put (can be zero)
    // - putUnlock: unlock time parameter for Put
    // - collectAmount: amount to attempt to collect
    // - doCollect: whether to call Collect after Put
    function run(uint putAmount, uint putUnlock, uint collectAmount, bool doCollect) public payable {
        require(address(this).balance >= putAmount + 1 wei);
        // record balances before
        uint beforeContractBalance = address(c).balance;
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));

        // Call Put with value putAmount
        c.Put{value: putAmount}(putUnlock);

        // observe after Put
        uint afterContractBalance = address(c).balance;
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));

        // basic invariant: recorded balance increased by exactly putAmount
        // and contract's ETH balance increased by exactly putAmount
        bool putConsistency = (afterBal == beforeBal + putAmount) && (afterContractBalance == beforeContractBalance + putAmount);

        bool collectReverted = false;
        uint afterCollectContractBalance = afterContractBalance;
        (uint finalUnlock, uint finalBal) = (afterUnlock, afterBal);
        if (doCollect) {
            // attempt Collect and catch revert
            try c.Collect(collectAmount) {
                collectReverted = false;
            } catch {
                collectReverted = true;
            }
            afterCollectContractBalance = address(c).balance;
            (finalUnlock, finalBal) = c.Acc(address(this));
        }

        // Now assert the general rule combining Put and Collect outcomes:
        // - Put must have been consistent as above.
        // - If we attempted Collect and it did NOT revert, then contract balance must have decreased by collectAmount
        //   and recorded balance must have decreased by collectAmount, and this contract's balance must have increased by collectAmount.
        // - If Collect reverted or was not attempted, then recorded balance must equal afterPut recorded balance.
        // We cannot directly read this contract's external balance before/after Collect easily (it changes only on successful Collect),
        // but we can assert consistency between c's storage and c's ETH balance.
        if (doCollect) {
            // If collect succeeded, c's stored balance and c's ETH balance both decrease by collectAmount compared to afterPut.
            assert(
                putConsistency && (
                    (collectReverted && finalBal == afterBal && afterCollectContractBalance == afterContractBalance)
                    || (!collectReverted && finalBal + collectAmount == afterBal && afterCollectContractBalance + collectAmount == afterContractBalance)
                )
            );
        } else {
            // Only Put happened: ensure Put consistency
            assert(putConsistency);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // putAmount: Ether to send to Put
    // putUnlock: unlock time passed to Put
    // collectAmount: amount to attempt to Collect
    // doCollect: whether to call Collect after Put
    function run(uint putAmount, uint putUnlock, uint collectAmount, bool doCollect) public payable {
        require(address(this).balance >= putAmount);

        // read before-Put observable state
        uint beforeContractBalance = address(c).balance;
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));

        // perform Put (state-changing call must be top-level)
        c.Put{value: putAmount}(putUnlock);

        // read after-Put observable state
        uint afterPutContractBalance = address(c).balance;
        (uint afterPutUnlock, uint afterPutBal) = c.Acc(address(this));

        bool collectReverted = false;
        uint afterCollectContractBalance = afterPutContractBalance;
        uint afterCollectBal = afterPutBal;

        if (doCollect) {
            // attempt Collect and catch revert
            try c.Collect(collectAmount) {
                collectReverted = false;
            } catch {
                collectReverted = true;
            }
            afterCollectContractBalance = address(c).balance;
            (uint tmpUnlock, uint tmpBal) = c.Acc(address(this));
            afterCollectBal = tmpBal;
        }

        // Single general assert covering both Put and optional Collect outcomes:
        // 1) Put increased both c's on-chain balance and the recorded balance by exactly putAmount.
        // 2) If Collect was attempted and did NOT revert, then both c's on-chain balance and the recorded balance
        //    decreased by exactly collectAmount compared to their values immediately after Put.
        // 3) If Collect was attempted and reverted, recorded balance and contract balance remain as after Put.
        assert(
            // Put consistency
            afterPutBal == beforeBal + putAmount
            && afterPutContractBalance == beforeContractBalance + putAmount
            && (
                // If no Collect attempted: final state equals afterPut
                (!doCollect && afterCollectBal == afterPutBal && afterCollectContractBalance == afterPutContractBalance)
                // If Collect attempted and it reverted: final state equals afterPut
                || (doCollect && collectReverted && afterCollectBal == afterPutBal && afterCollectContractBalance == afterPutContractBalance)
                // If Collect attempted and it succeeded: both balances decreased by collectAmount
                || (doCollect && !collectReverted && afterCollectBal + collectAmount == afterPutBal && afterCollectContractBalance + collectAmount == afterPutContractBalance)
            )
        );
    }

    receive() external payable {}
}

