        // read pre-state: recorded balance for this test contract in c and c's Ether balance
        uint balBeforeHolder = c.Acc(address(this)).balance;
        uint cBalBefore = address(c).balance;

        // perform Put to deposit funds and set unlockTime (via fallback Put(0) or direct)
        c.Put{value: deposit}(unlockTime);

        // after Put, read holder balance and contract balance
        uint balAfterPutHolder = c.Acc(address(this)).balance;
        uint cBalAfterPut = address(c).balance;

        // basic sanity: recorded balance increases by exactly deposit
        // (we will assert the stronger invariant after Collect below; this ensures Put succeeded)
        // Now attempt Collect: it may revert (if conditions not met). Capture whether it reverted.
        bool reverted;
        // prepare c's balance snapshot before Collect
        uint balBeforeCollectHolder = c.Acc(address(this)).balance;
        uint cBalBeforeCollect = address(c).balance;
        try c.Collect{value: 0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
