contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will provide parameters to Put and Collect. We must fund this contract before sending value to c.
    // The test function is payable so the harness can send Ether to this contract.
    function run(uint unlockTimePut, uint putAmount, uint collectAmount) public payable {
        // allow any inputs; require we have enough balance to forward putAmount
        require(address(this).balance >= putAmount);

        // 1) Record balance and holder info before actions
        // Note: Acc is a public mapping with getter Acc(address) returns (uint unlockTime, uint balance)
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        // 2) Put some funds into c from this contract to set up possible Collect
        // Use top-level state-changing call
        c.Put{value: putAmount}(unlockTimePut);

        // read state after Put, before Collect
        (uint afterPutUnlock, uint afterPutBal) = c.Acc(address(this));
        uint cBalAfterPut = address(c).balance;

        // Consistency: afterPutBal should be beforeBal + putAmount (or at least >= beforeBal)
        // We won't assert that here; it's only setup.

        // 3) Attempt to Collect collectAmount and observe if it reverts
        bool reverted;
        // Collect is payable but does not require sending funds; it's invoked without value
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // 4) Read final state
        (uint finalUnlock, uint finalBal) = c.Acc(address(this));
        uint cBalFinal = address(c).balance;

        // 5) Assert general invariant about successful vs unsuccessful Collect effects
        // If Collect did not revert and it actually transferred (i.e., finalBal == afterPutBal - collectAmount and c balance decreased),
        // then both holder balance and contract balance decreased by exactly collectAmount.
        // Otherwise (reverted or did nothing), holder balance is unchanged.
        bool successfulCollect = (!reverted) && (afterPutBal >= collectAmount) && (block.timestamp > afterPutUnlock) && (finalBal + collectAmount == afterPutBal) && (cBalAfterPut == cBalFinal + collectAmount);

        bool noEffectCollect = (finalBal == afterPutBal) && (cBalAfterPut == cBalFinal);

        assert(successfulCollect || noEffectCollect);
    }

    // receive to accept Ether for forwarding in run
    receive() external payable {}
}
